    "description": "民生实事，连着柴米油盐，反映着治理成色。比如，停水停电、积水内涝、困难帮扶等燃眉之急，需干部闻令而动；老旧小区改造、街区更新等长久之功，提醒干部谋定后动。找准民生工作的时间坐标，读懂“快”与“慢”的辩证之道，既解眼前之急，又谋长远之安，方能把好事办实、把实事办到群众心坎上。",
