    "content": "台湾星期六（11月28日）举行九合一选举，现任台中市长卢秀燕上午先陪国民党籍台中市长候选人江启臣投票，再回到自己的户籍地投票。 综合台湾《联合报》《自由时报》报道，卢秀燕陪江启臣夫妻投票，并说她从政30年，从来没陪过人投票，今天是第一次，因为她与江启臣姐弟情深，在他最关键的时刻，希望陪陪他。 卢秀燕也是寻求连任的台北市长蒋万安市长竞总主委。她在回应关于是否会北上的提问时说，视情况可能北上蒋万安总部。 卢秀燕之后回到自己的户籍地投票，不到五分钟便完成。她也说，今天心情不错，主要是因为难得有好天气，非常凉爽舒适，是投票…"
