    "description": "11月30日清晨，金星将以“启明星”身份迎来本年度最大亮度，约-4.9等，以微弱优势超越9月它作为“长庚星”时的亮度峰值，登顶“年度最亮”。 金星是怎么在短短两个多月两度迎来亮度峰值的？两次最大亮度又为啥如此接近？中国科学院紫金山天文台科普主管王科超介绍，作为一颗地内行星，金星的轨道比地球更接近太阳，它的亮度主要受两方面影响：一是与地球的距离，二是相位，也就是被太阳照亮部分占视圆面的比例。金星越靠近地球，看起来越大，但相位在变小，因此二…",
    "content": "11月30日清晨，金星将以“启明星”身份迎来本年度最大亮度，约-4.9等，以微弱优势超越9月它作为“长庚星”时的亮度峰值，登顶“年度最亮”。 金星是怎么在短短两个多月两度迎来亮度峰值的？两次最大亮度又为啥如此接近？中国科学院紫金山天文台科普主管王科超介绍，作为一颗地内行星，金星的轨道比地球更接近太阳，它的亮度主要受两方面影响：一是与地球的距离，二是相位，也就是被太阳照亮部分占视圆面的比例。金星越靠近地球，看起来越大，但相位在变小，因此二者也会相互影响。 在金星与地球的一轮约584天会合周期中，金星依次经过上合、东大…"
