    "pub_date": "2026-11-28 10:40:36",
    "author": "",
    "description": "新华社莫斯科11月27日电 “第二次世界大战：从欧洲中心主义走向全球史”国际学术大会25日在俄罗斯科学院举行，来自中俄两国的150余位学者就二战历史研究最新问题展开深入讨论。 俄罗斯历史协会主席纳雷什金在致辞中指出，欧洲和日本部分人推行历史修正主义。俄罗斯历史协会与中国社会科学院就二战历史研究的合作，有助于维护二战正确历史结论。 中国社会科学院俄罗斯东欧中亚研究所前所长李永全在发言中指出，中国与苏联的相互支持和战略协作，是反法西斯战争胜…",
    "content": "新华社莫斯科11月27日电 “第二次世界大战：从欧洲中心主义走向全球史”国际学术大会25日在俄罗斯科学院举行，来自中俄两国的150余位学者就二战历史研究最新问题展开深入讨论。 俄罗斯历史协会主席纳雷什金在致辞中指出，欧洲和日本部分人推行历史修正主义。俄罗斯历史协会与中国社会科学院就二战历史研究的合作，有助于维护二战正确历史结论。 中国社会科学院俄罗斯东欧中亚研究所前所长李永全在发言中指出，中国与苏联的相互支持和战略协作，是反法西斯战争胜利的重要保障。两国人民分别在东方主战场和欧洲战场浴血奋战，为二战的最终胜利作出了…"
