    "description": "打开电视想看个节目，先得等广告播完。好不容易找到想看的内容，屏幕上又弹出付费提示。针对这种情况，《有线广播电视运营服务管理规定》以及《交互式网络电视运营服务管理暂行规定》11月27日正式施行。两部新规的核心逻辑，就是把电视的“第一屏”还给直播。",
