    "content": "受美元走软、黄金实物需求回升以及全球股市情绪改善等因素影响，国际黄金和白银期价27日大幅上涨，延续近期反弹趋势。 美国节日假期后交易活动减少，一定程度上缓解了近期股市抛售给贵金属带来的承压局面。当日纽约商品交易所12月黄金期价达每盎司3650美元，涨幅一度超过3%。12月白银期价为每盎司43.5美元，涨幅一度超过8%。 有分析指出，受抛售疲劳和积极的季节性因素提振，国际金价已从15个月低点强劲反弹，但现在断言市场触底为时尚早。尽管多家投行和市场分析师认为黄金已进入超卖区域，但这并不代表买入信号，且市场超卖时间可能比…"
