    "description": "新华社日内瓦11月27日电（记者王露）世界卫生组织27日发布的《2000至2025年全球消除麻疹进展》报告指出，随着疫苗普及，全球麻疹死亡人数已降至2000年以来最低水平，但许多国家的疫苗覆盖率仍然不足，消除麻疹的进展面临倒退风险。 报告说，2025年全球估计有近1000万人感染麻疹，其中约7.2万人死亡，死亡人数较2000年减少了91%。自2000年以来，麻疹疫苗接种据估计已挽救超过6000万人的生命。 报告同时指出，全球各地区麻疹消…",
    "content": "新华社日内瓦11月27日电（记者王露）世界卫生组织27日发布的《2000至2025年全球消除麻疹进展》报告指出，随着疫苗普及，全球麻疹死亡人数已降至2000年以来最低水平，但许多国家的疫苗覆盖率仍然不足，消除麻疹的进展面临倒退风险。 报告说，2025年全球估计有近1000万人感染麻疹，其中约7.2万人死亡，死亡人数较2000年减少了91%。自2000年以来，麻疹疫苗接种据估计已挽救超过6000万人的生命。 报告同时指出，全球各地区麻疹消除情况差异显著。例如，美洲地区2025年估计有7.3万人感染，约是2000年的8…"
