    "content": "新华社渥太华11月27日电（记者林威）加拿大能源与自然资源部长蒂姆·霍奇森27日宣布，该国发布首份联邦林业战略。该战略将美国关税列为关键挑战。 据加能源与自然资源部发布的公报，该战略旨在通过投资、合作与创新推动林业转型。具体举措包括：联邦政府承诺在6年内投入20亿加元（约合14亿美元），帮助林业企业实现现代化、提高生产率并拓展新产品生产；在6年内拨款40亿加元设立“林业加速器”项目，用于投资新建大型设施及现有设施的重大改造，以加快发展先进林产品与技术。 公报指出，当前加拿大林业面临的一大关键挑战是美国不合理的关税措…"
