    "description": "Character Technologies的债权人委员会拟向该公司前首席执行官（现任华特迪士尼首席技术官）发出传票，这家传媒巨头正计划从这家娱乐AI初创企业授权部分知识产权。无担保债权人官方委员会周五向美国特拉华州破产法院提交通知，拟在12月4日听证会前传唤卡兰迪普·阿南德作证。阿南德于9月出任迪士尼首任首席技术官。领英信息显示，他在加入迪士尼前，曾在Character.ai任职两年。（新浪财经）",
    "content": "Character Technologies的债权人委员会拟向该公司前首席执行官（现任华特迪士尼首席技术官）发出传票，这家传媒巨头正计划从这家娱乐AI初创企业授权部分知识产权。无担保债权人官方委员会周五向美国特拉华州破产法院提交通知，拟在12月4日听证会前传唤卡兰迪普·阿南德作证。阿南德于9月出任迪士尼首任首席技术官。领英信息显示，他在加入迪士尼前，曾在Character.ai任职两年。（新浪财经）"
