    "description": "新华社达喀尔11月27日电（记者陈晨 齐琪）由中国国家广播电视总局与塞内加尔通信和机构关系部主办、广电总局广播电视科学研究院承办的“中非广电视听人工智能应用培训班·塞内加尔站”27日在塞内加尔首都达喀尔开班，助力当地媒体从业者提升人工智能应用能力。 塞内加尔通信和机构关系部长巴卡里·萨尔在开班仪式上说，中国在人工智能、电信、广播和视听创新领域的经验，为塞内加尔有关机构提供了重要学习机会。他表示，双方应通过系统性培训、专家交流、应用研究和…",
    "content": "新华社达喀尔11月27日电（记者陈晨 齐琪）由中国国家广播电视总局与塞内加尔通信和机构关系部主办、广电总局广播电视科学研究院承办的“中非广电视听人工智能应用培训班·塞内加尔站”27日在塞内加尔首都达喀尔开班，助力当地媒体从业者提升人工智能应用能力。 塞内加尔通信和机构关系部长巴卡里·萨尔在开班仪式上说，中国在人工智能、电信、广播和视听创新领域的经验，为塞内加尔有关机构提供了重要学习机会。他表示，双方应通过系统性培训、专家交流、应用研究和专业机构合作，建立长期合作机制，持续提升媒体从业者能力，推动媒体现代化发展。 中…"
