    "description": "人民网北京11月26日电 (记者梁军)神舟二十四号航天员乘组25日顺利进驻“天宫”，来自巴基斯坦的航天员穆罕默德·齐尚·阿里成为首个到访中国“天宫”的外籍航天员。国际媒体纷纷关注这一历史性时刻，多家媒体从中国航天国际合作、中巴科技合作以及全球空间科研合作等角度展开报道。",
    "content": "人民网北京11月26日电 (记者梁军)神舟二十四号航天员乘组25日顺利进驻“天宫”，来自巴基斯坦的航天员穆罕默德·齐尚·阿里成为首个到访中国“天宫”的外籍航天员。国际媒体纷纷关注这一历史性时刻，多家媒体从中国航天国际合作、中巴科技合作以及全球空间科研合作等角度展开报道。"
