    "description": "2026年11月28日 赣南初冬，连片丘陵披上金黄。江西省赣州市信丰县大塘埠镇长岗村的正大橙园里，山风一吹，果香扑鼻。 “咔嚓”一声，一颗名叫“赣小橙”的脐橙被果农从枝头剪下，从这里出发，将踏上一段新旅程。这段旅程，一头连着一条年产值超230亿元、品牌价值近700亿元的产业链，一头连着上百万老区群众的幸福生活。 赣南脐橙树，曾是帮老区拔掉穷根的“当家树”。 2023年10月，习近平总书记在江西考察时强调：“坚持产业兴农、质量兴农、绿色兴…",
