    "description": "2026年11月28日 当地时间11月27日，联合国阿卜耶伊临时安全部队（联阿安全部队）在司令部超级营地举行授勋仪式，授予中国第六批赴阿卜耶伊维和直升机分队120名维和官兵“和平荣誉勋章”，联阿安全部队高层及所有出兵国指挥官到场参加。 黄炜鑫 黄 浩摄影报道 2026-11-28 00:00:00:0 30193539 10http://paper.people.com.cn/rmrb/pc/content/202611/28/cont…",
