    "description": "2026年11月28日 屏幕上，跨境电商平台的后台正跳动着实时数据，来自海外的订单不断涌入。“跨境电商业务开通小半年，现在每天稳定在100多单。”辽阳禹呈纺织科技有限公司总经理郭健说，过去给外贸商供货，要过几道手才能到海外；现在通过跨境电商，直发海外顾客，利润高还方便。 辽宁省辽阳县小北河镇，这个拥有50余年制袜历史的小镇，如今越来越多的企业开通了跨境电商业务。“政府帮我们梳理资源渠道，物流有指导，认证费、检验检测费都有支持，让我们‘敢…",
    "content": "2026年11月28日 屏幕上，跨境电商平台的后台正跳动着实时数据，来自海外的订单不断涌入。“跨境电商业务开通小半年，现在每天稳定在100多单。”辽阳禹呈纺织科技有限公司总经理郭健说，过去给外贸商供货，要过几道手才能到海外；现在通过跨境电商，直发海外顾客，利润高还方便。 辽宁省辽阳县小北河镇，这个拥有50余年制袜历史的小镇，如今越来越多的企业开通了跨境电商业务。“政府帮我们梳理资源渠道，物流有指导，认证费、检验检测费都有支持，让我们‘敢出海、会出海’。”郭健说。 在辽宁，跨境电商正破局起势，各项指标迎来大幅增长。今…"
