    "description": "2026年11月28日 随着“个子”越长越高、“体格”越发健硕，高技术制造业必将为经济发展注入更多源源不断的新动能。 1至10月份，全国规模以上工业企业利润同比增长16.0%，较1至9月份加快0.5个百分点；其中10月当月同比增长20.1%，较9月份加快5.7个百分点……27日国家统计局发布的数据显示，当前我国工业生产总体平稳，新动能正快速成长。 细读利润“晴雨表”，能看到产业持续优化升级的强劲势头。 商业航天新赛道“百舸争流”，为航天…",
