    "content": "2026年11月28日 本报北京11月27日电&nbsp;&nbsp;（记者李卓尔）由中共中央党校（国家行政学院）和中国外文局联合出品，中共中央党校（国家行政学院）科研部和解读中国工作室策划制作的系列英文演讲节目《党校公开课（中国故事）》（第一季），于11月24日起正式上线播出。 节目聚焦习近平总书记关于扶贫脱贫工作的重要论述，邀请8位中共中央党校（国家行政学院）专家学者以全英文演讲形式开讲，深度融合典型地域案例，分享中国脱贫攻坚的实践和经验。 节目生动阐释中国脱贫攻坚的理论逻辑、实践路径与世界意义，立足人类减贫事…"
