    "content": "2026年11月28日 本报北京11月27日电&nbsp;&nbsp;（记者易舒冉）记者27日从全国总工会获悉：近日，全国总工会、人力资源社会保障部、国家卫生健康委、中国企业联合会/中国企业家协会、全国工商联联合印发《家庭友好型工作场所建设工作指引（试行）》。 据介绍，家庭友好型工作场所是指用人单位通过完善优化工作管理制度，打造安全有尊严的、有利于职工身心健康的职场环境，支持男女职工平衡工作、家庭和个人生活，保障职工在身心健康的状态下投入工作的场所。 指引充分发挥三方机制在构建和谐劳动关系方面的作用，首次在政策层面…"
