    "description": "2026年11月28日 今年是人类基因组计划第一份草图公布25年。昌平实验室举办人类基因组序列草图发表25年国际研讨会，来自多个国家和地区的百余名科学家共同探讨基因组学的前景与未来。 人类基因组为何被称为生命的“天书”？科学家如何通过基因的“文字”找到守护人类健康的“密码”？基因组学对我们的生活有什么影响？本期“院士讲科普”，邀请中国科学院院士、昌平实验室主任谢晓亮带我们了解生命“天书”背后的科学奥妙。 ——编 者 读“天书”，解读生命…",
