    "author": "",
    "description": "2026年11月28日 本报北京电 （记者李红梅）在2026雄安气象人工智能国际研讨会上，地球系统智能科研平台“ZHU·GE（诸葛）”正式推出。 “ZHU·GE”由中国气象局与上海人工智能实验室共同牵头研发，重点推进海量气象数据和大气科学知识接入、研究框架改造及场景试验，可将科研想法快速转化为有海量数据支撑、可分析、可验证的科学研究结论，助力科学认识落地转化为业务能力。目前，平台汇集约10PB（拍字节）公共科学数据、首批1PB中国气象局…",
    "content": "2026年11月28日 本报北京电&nbsp;&nbsp;（记者李红梅）在2026雄安气象人工智能国际研讨会上，地球系统智能科研平台“ZHU·GE（诸葛）”正式推出。 “ZHU·GE”由中国气象局与上海人工智能实验室共同牵头研发，重点推进海量气象数据和大气科学知识接入、研究框架改造及场景试验，可将科研想法快速转化为有海量数据支撑、可分析、可验证的科学研究结论，助力科学认识落地转化为业务能力。目前，平台汇集约10PB（拍字节）公共科学数据、首批1PB中国气象局授权数据、约200万条文献记录，并内置5000余项代码工具…"
