    "description": "2026年11月28日 据新华社广州电 （记者马晓澄）国产120千伏冷冻透射电子显微镜TH—F120C日前在广东广州发布，这是我国推进高端科学仪器自主可控的一项突破，将为科研人员提供解析生物大分子结构、研究先进材料微观特性的重要工具。 该成果源自广东省重点领域研发计划精密仪器设备专项，在广东省科技厅支持下，由生物岛实验室牵头，联合广州实验室、广州生物医药与健康研究院等科研单位历经5年攻坚克难实现整机突破。2025年10月，团队与中国钢研…",
    "content": "2026年11月28日 据新华社广州电&nbsp;&nbsp;（记者马晓澄）国产120千伏冷冻透射电子显微镜TH—F120C日前在广东广州发布，这是我国推进高端科学仪器自主可控的一项突破，将为科研人员提供解析生物大分子结构、研究先进材料微观特性的重要工具。 该成果源自广东省重点领域研发计划精密仪器设备专项，在广东省科技厅支持下，由生物岛实验室牵头，联合广州实验室、广州生物医药与健康研究院等科研单位历经5年攻坚克难实现整机突破。2025年10月，团队与中国钢研集团所属上市企业开展产学研协同。 冷冻电镜是生命科学研究、…"
