    "author": "",
    "description": "2026年11月28日 本报呼和浩特电 （记者张枨）记者从内蒙古自然博物馆获悉：由内蒙古自然博物馆、云南大学、中国科学院古脊椎动物与古人类研究所、沈阳师范大学等单位组成的联合科研团队，在国际古生物期刊《Fossil Record》发表论文，报道了在二连盆地首次发现的早白垩世鸭嘴龙超科恐龙化石。该化石采自内蒙古锡林郭勒盟东乌珠穆沁旗额吉淖尔镇，是二连盆地下白垩统首例鸭嘴龙超科化石记录。 鸭嘴龙超科是白垩纪最为繁盛的植食恐龙类群之一。此次发…",
    "content": "2026年11月28日 本报呼和浩特电&nbsp;&nbsp;（记者张枨）记者从内蒙古自然博物馆获悉：由内蒙古自然博物馆、云南大学、中国科学院古脊椎动物与古人类研究所、沈阳师范大学等单位组成的联合科研团队，在国际古生物期刊《Fossil Record》发表论文，报道了在二连盆地首次发现的早白垩世鸭嘴龙超科恐龙化石。该化石采自内蒙古锡林郭勒盟东乌珠穆沁旗额吉淖尔镇，是二连盆地下白垩统首例鸭嘴龙超科化石记录。 鸭嘴龙超科是白垩纪最为繁盛的植食恐龙类群之一。此次发现表明早白垩世鸭嘴龙超科已在二连盆地繁衍生息。 研究表明，…"
