    "pub_date": "2026-11-28 08:26:03",
    "author": "",
    "description": "2026年11月28日 四川省文物考古研究院供图 \"> 金光闪闪的三星堆金面具，实际却正在悄然变脆。在保护修复过程中，我们发现，部分三星堆金面具的缺损边缘出现“掉渣”，仍有金属光泽的残片已十分脆弱。 看不见的损伤背后，常常藏着肉眼难辨的微观腐蚀。怎样找到这些隐蔽的薄弱处，又怎样为它们选对保护材料？围绕三星堆金面具的脆化现象，研究人员用超微探针绘出“腐蚀地图”，逐步揭开微观腐蚀的秘密，明确缓蚀材料的筛选方向。 为什么通常耐腐蚀、易延展的金…",
    "content": "2026年11月28日 三星堆金面具。 四川省文物考古研究院供图 \"> 金光闪闪的三星堆金面具，实际却正在悄然变脆。在保护修复过程中，我们发现，部分三星堆金面具的缺损边缘出现“掉渣”，仍有金属光泽的残片已十分脆弱。 看不见的损伤背后，常常藏着肉眼难辨的微观腐蚀。怎样找到这些隐蔽的薄弱处，又怎样为它们选对保护材料？围绕三星堆金面具的脆化现象，研究人员用超微探针绘出“腐蚀地图”，逐步揭开微观腐蚀的秘密，明确缓蚀材料的筛选方向。 为什么通常耐腐蚀、易延展的金质文物会掉渣变脆？显微分析发现，金面具并非由纯金制成，其金银合金…"
