    "description": "2026年11月28日 1990年至1992年发掘的悬泉置遗址，出土简牍3.5万余枚，其中有字者2.3万余枚。在房屋倒塌的灰土中，还发掘出很多墙壁题记残块，或称之为“壁书”。 汉代文献保存的形态主要有简牍与碑刻。悬泉壁书的发现证明，在二者之外，汉代还存在第三种形态——直接题写在官署墙壁上的“公示文书”。这些壁书写在驿置办公用房的“显见处”，往来吏卒、使者、商旅抬头可见。 与史籍比定、性质明确的墙壁诏书有三件。 其一是汉成帝建始元年（公元…",
