    "content": "新华社墨西哥城11月27日电（记者翟淑睿 吴昊）墨西哥总统辛鲍姆27说，墨方已就美国毒品管制局在墨开通举报渠道一事向美方提出正式抗议，谴责美方此举是对墨又一轮干涉。 辛鲍姆当天在总统府早间新闻发布会上表示，美国毒品管制局在墨西哥锡那罗亚州和哈利斯科州设立举报渠道，征集有关腐败官员、有组织犯罪成员以及洗钱活动的举报信息，墨外交部已就此向美国驻墨大使提出正式抗议。 辛鲍姆强调，墨美关系是“协调关系”，而非“从属关系”。她表示，墨西哥拥有自己的执法和司法机构，有能力调查本国境内发生的犯罪活动，美国应打击在美境内活动的贩毒…"
