    "title": "英国就业和养老金部因“网络事件”中断部分线上服务",
    "link": "http://www.news.cn/20261128/3269621962e847c4af3de947024d9563/c.html",
    "pub_date": "2026-11-28 07:12:26",
    "author": "",
    "description": "新华社伦敦11月27日电（记者李鲲）英国就业和养老金部27日发布消息称，由于发现影响系统的“网络事件”，该部门中断部分线上服务。 该部门表示，正与英国国家网络安全中心及政府网络协调中心密切合作展开调查，努力尽快恢复相关线上服务以将影响降到最低。消息称，常规的福利和养老金发放不受影响，将照常支付。 英国就业和养老金部同时提醒公众，该部门不会通过短信或电子邮件索要私人信息，注意防范并举报网络诈骗和网络钓鱼。 据英国媒体报道，这起“网络事件”…",
    "content": "新华社伦敦11月27日电（记者李鲲）英国就业和养老金部27日发布消息称，由于发现影响系统的“网络事件”，该部门中断部分线上服务。 该部门表示，正与英国国家网络安全中心及政府网络协调中心密切合作展开调查，努力尽快恢复相关线上服务以将影响降到最低。消息称，常规的福利和养老金发放不受影响，将照常支付。 英国就业和养老金部同时提醒公众，该部门不会通过短信或电子邮件索要私人信息，注意防范并举报网络诈骗和网络钓鱼。 据英国媒体报道，这起“网络事件”导致数百万人无法使用在线福利和养老金服务。英国就业和养老金大臣帕特·麦克法登表示…"
