    "content": "新华社纽约11月27日电 纽约股市三大股指27日显著上涨。 截至当天收盘，道琼斯工业平均指数比前一交易日上涨591.99点，收于50774.94点，涨幅为1.18%；标准普尔500种股票指数上涨114.71点，收于7297.49点，涨幅为1.60%；纳斯达克综合指数上涨543.70点，收于24129.50点，涨幅为2.31%。 板块方面，标普500指数十一大板块全线上涨。非必需消费品板块和科技板块分别以2.72%和2.23%的涨幅领涨，公用事业板块涨幅最小，为0.15%。"
