    "content": "新华社莫斯科11月27日电（记者赵冰）俄罗斯总统普京27日在新型核动力潜艇“彼尔姆”号入列升旗仪式上表示，该核潜艇将加入俄太平洋舰队并执行战斗值班任务。 “彼尔姆”号入列升旗仪式当天在俄西北部阿尔汉格尔斯克州北德文斯克市举行。普京发表讲话称，“彼尔姆”号是俄海军过去6年间接收的第5艘“亚森-M”级核潜艇。他说，俄罗斯是世界上少数有能力建造此类先进核潜艇的国家之一，这类核潜艇属于具备全球战略意义的武器装备。 普京说，“亚森-M”级多用途核潜艇符合当前及未来作战要求，是俄海军作战体系的重要组成部分。该型潜艇可在世界大洋…"
