    "content": "关于中国经济温度差的讨论，从今年初一直延续到年底。 多家中国官媒本周接连发文，剖析宏观经济数据与微观个体感受间的差异。网红政务公众号“浙江宣传”更是连发四篇长文，驳斥借消费和房地产市场低迷唱衰中国经济的论调。四篇文章的阅读量均突破10万次，相关话题还登上社媒热搜。 以星期一（11月23日）发布的《 中国消费降级是伪命题 》为例，文章指线下商场人流量减少、实体门店热度不如从前“只是消费场景的迁移”；奢侈品和名牌商品销量下降，则是“从刚需物质消费向精神、健康、体验型消费的进阶”。 两天后，“浙江宣传”又发表题为《 借房…"
